/**
 * End-to-end checks against the synthetic test recording.
 *
 *   npm test
 *
 * The recording generated by `scripts/make-test-wav.mjs` has a known melody,
 * bass line and key, so the pipeline's output can be checked against it
 * instead of against a vague idea of "looks right".
 *
 * The last group of tests is the important one for anyone using this as a
 * tool: they check that the output does not drift. The same recording has to
 * produce the same bytes every time, and the weights on disk have to be the
 * ones the pipeline was tuned against.
 */

import nodeUtil from 'node:util';

const mutableUtil = nodeUtil as typeof nodeUtil & { isNullOrUndefined?: (value: unknown) => boolean };
if (typeof mutableUtil.isNullOrUndefined !== 'function') {
  mutableUtil.isNullOrUndefined = (value: unknown) => value === null || value === undefined;
}
await import('@tensorflow/tfjs-node');

import { readFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import test from 'node:test';
import assert from 'node:assert/strict';

import { decodeAudio, prepareMono } from '../src/core/audio';
import { nodeAudioDecoder } from '../src/core/audio-node';
import { loadPinnedModel } from '../src/core/basic-pitch';
import {
  assertContractMatches,
  assertModelMatches,
  ModelLock,
  ModelSource,
  sha256Hex,
} from '../src/core/model';
import modelLock from '../src/core/model.lock.json';
import { transcribe } from '../src/core/pipeline';
import { buildMidiFile } from '../src/core/midi';
import { provenanceFor, PIPELINE_VERSION } from '../src/core/version';
import { modelFrameToTime, timeToModelFrame, midiToHz, SAMPLE_RATE } from '../src/core/constants';
import { RawNote, Track } from '../src/core/types';

const BPM = 120;
const BEAT = 60 / BPM;

/** The melody the test recording plays, in the order it is played. */
const EXPECTED_MELODY = [
  60, 64, 67, 69,
  72, 67, 64, 62,
  60, 64, 67, 72,
  74, 71, 69, 67,
];

/** The bass note at the start of each bar. */
const EXPECTED_BASS = [43, 43, 48, 50];

/** When each melody note starts, in seconds. */
function expectedMelodyTimes(): number[] {
  const times: number[] = [];
  for (let bar = 0; bar < 4; bar++) {
    for (let beat = 0; beat < 4; beat++) times.push((bar * 4 + beat) * BEAT);
  }
  return times;
}

/** Read the model off disk, the way the command line does. */
function nodeModelSource(modelPath: string): ModelSource {
  const directory = dirname(modelPath);
  return {
    url: pathToFileURL(modelPath).href,
    read: async (name: string) => {
      const bytes = await readFile(join(directory, name));
      return bytes.buffer.slice(
        bytes.byteOffset,
        bytes.byteOffset + bytes.byteLength,
      ) as ArrayBuffer;
    },
  };
}

const MODEL_PATH = resolve('public/model/model.json');
const LOCK = modelLock as ModelLock;

let model: Awaited<ReturnType<typeof loadPinnedModel>>;
let samples: Float32Array;
let result: Awaited<ReturnType<typeof transcribe>>;

test.before(async () => {
  model = await loadPinnedModel(nodeModelSource(MODEL_PATH), LOCK);

  const data = await readFile(resolve('test/sample.wav'));
  const audio = await decodeAudio(
    data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength) as ArrayBuffer,
    nodeAudioDecoder,
  );
  samples = prepareMono(audio);
  result = await transcribe(samples, { model });
});

test.after(() => {
  model?.dispose();
});

function track(kind: string): Track | undefined {
  return result.tracks.find((t) => t.kind === kind);
}

/**
 * How many expected notes are matched by a transcribed note of the same
 * pitch starting close enough to be the same note.
 */
function matchCount(expected: number[], times: number[], notes: RawNote[], tolerance: number): number {
  let matched = 0;
  for (let i = 0; i < expected.length; i++) {
    const hit = notes.some(
      (note) => note.pitchMidi === expected[i] && Math.abs(note.startTime - times[i]) <= tolerance,
    );
    if (hit) matched += 1;
  }
  return matched;
}

test('decodes the test recording at the right length', () => {
  assert.ok(Math.abs(result.duration - 8) < 0.1, `duration was ${result.duration}`);
});

test('estimates the tempo', () => {
  assert.ok(
    Math.abs(result.tempo.bpm - BPM) <= 1,
    `tempo was ${result.tempo.bpm}, expected about ${BPM}`,
  );
});

test('estimates the key', () => {
  assert.equal(result.key.tonic, 0, 'expected C');
  assert.equal(result.key.mode, 'major');
});

test('finds the melody', () => {
  const melody = track('melody');
  assert.ok(melody, 'no melody track');
  assert.ok(melody.notes.length > 0, 'melody track is empty');

  const times = expectedMelodyTimes();
  const matched = matchCount(EXPECTED_MELODY, times, melody.notes, 0.12);
  assert.ok(
    matched >= EXPECTED_MELODY.length * 0.8,
    `only matched ${matched} of ${EXPECTED_MELODY.length} melody notes`,
  );
});

test('finds the bass line', () => {
  const bass = track('bass');
  assert.ok(bass, 'no bass track');

  // The bass plays its root on beats 1 and 3 of each bar.
  const expected: number[] = [];
  const times: number[] = [];
  for (let bar = 0; bar < 4; bar++) {
    for (const beat of [0, 2]) {
      expected.push(EXPECTED_BASS[bar]);
      times.push((bar * 4 + beat) * BEAT);
    }
  }

  const matched = matchCount(expected, times, bass.notes, 0.15);
  assert.ok(matched >= expected.length * 0.6, `only matched ${matched} of ${expected.length} bass notes`);
});

test('detects the drum kit', () => {
  assert.ok(result.stats.drumsDetected, 'no drums detected');
  const drums = track('drums');
  assert.ok(drums, 'no drum track');
  assert.ok(drums.notes.length > 8, `only ${drums.notes.length} drum hits`);

  // Every hit should be on one of the three General MIDI drum notes.
  for (const note of drums.notes) {
    assert.ok([36, 38, 42].includes(note.pitchMidi), `unexpected drum pitch ${note.pitchMidi}`);
  }
});

test('writes a readable MIDI file', () => {
  const bytes = buildMidiFile(result.tracks, result.tempo, result.key);
  assert.equal(String.fromCharCode(...bytes.slice(0, 4)), 'MThd');
  assert.equal(bytes.length > 100, true);

  // Format 1, one track per part plus a conductor track.
  const format = (bytes[8] << 8) | bytes[9];
  const trackCount = (bytes[10] << 8) | bytes[11];
  assert.equal(format, 1);
  assert.equal(trackCount, result.tracks.length + 1);

  // Every track must be a well formed MTrk chunk.
  const buffer = Buffer.from(bytes);
  let chunks = 0;
  let offset = 0;
  while (offset < buffer.length - 8) {
    if (buffer.toString('latin1', offset, offset + 4) === 'MTrk') {
      chunks += 1;
      offset += 8 + buffer.readUInt32BE(offset + 4);
    } else {
      offset += 1;
    }
  }
  assert.equal(chunks, trackCount);
});

// --- The frequency range -----------------------------------------------
//
// The range selects notes out of a finished transcription. It never changes
// the transcription itself, and it never touches the audio: a model that was
// given a low-passed recording finds far fewer of the notes it should.

test('the range keeps only the notes inside it', async () => {
  const limited = await transcribe(samples, { model, range: { low: 0, high: 400 } });

  const kept = limited.tracks.flatMap((track) => track.notes);
  assert.ok(kept.length > 0, 'the range kept nothing at all');

  for (const track of limited.tracks) {
    if (track.kind === 'drums') continue;
    for (const note of track.notes) {
      assert.ok(
        midiToHz(note.pitchMidi) <= 400,
        `a note at ${midiToHz(note.pitchMidi).toFixed(0)} Hz survived a 400 Hz ceiling`,
      );
    }
  }
});

test('the range keeps the low notes and drops the high ones', async () => {
  const limited = await transcribe(samples, { model, range: { low: 0, high: 400 } });

  const bass = limited.tracks.find((track) => track.kind === 'bass');
  assert.ok(bass && bass.notes.length > 0, 'the bass line was lost');

  // The melody reaches up to D5, which is above the ceiling.
  const melody = limited.tracks.find((track) => track.kind === 'melody');
  assert.ok(melody, 'no melody track');
  assert.ok(
    melody.notes.every((note) => midiToHz(note.pitchMidi) <= 400),
    'a melody note above the ceiling survived',
  );
});

test('the range does not change the notes that are inside it', async () => {
  const limited = await transcribe(samples, { model, range: { low: 0, high: 400 } });

  const describe = (tracks: Track[]) =>
    tracks
      .flatMap((track) =>
        track.notes.map((note) => `${track.kind}:${note.pitchMidi}:${note.startTime}`),
      )
      .sort();

  const full = describe(result.tracks);
  for (const kept of describe(limited.tracks)) {
    assert.ok(full.includes(kept), `the range invented a note: ${kept}`);
  }
});

test('the range does not change the tempo', async () => {
  const limited = await transcribe(samples, { model, range: { low: 0, high: 400 } });
  assert.equal(limited.tempo.bpm, result.tempo.bpm);
});

// --- The grid ----------------------------------------------------------
//
// A game that renders 30 frames a second can only show a note on one of its
// own frames, so the file is better off agreeing with the frames.

test('the grid snaps the notes to its slots', async () => {
  const snapped = await transcribe(samples, { model, quantise: { grid: 30 } });

  const period = 1 / 30;
  const notes = snapped.tracks.flatMap((track) => track.notes);
  assert.ok(notes.length > 0, 'the grid threw the notes away');

  for (const note of notes) {
    const slots = note.startTime / period;
    assert.ok(
      Math.abs(slots - Math.round(slots)) < 1e-6,
      `a note at ${note.startTime.toFixed(4)}s is not on a slot`,
    );
  }
});

test('the grid moves the notes by less than half a slot', async () => {
  const snapped = await transcribe(samples, { model, quantise: { grid: 30 } });
  const half = 1 / 60;

  const before = result.tracks.flatMap((track) =>
    track.notes.map((note) => ({
      kind: track.kind,
      pitch: note.pitchMidi,
      start: note.startTime,
    })),
  );

  for (const track of snapped.tracks) {
    for (const note of track.notes) {
      // Every snapped note has to be the same note as one the model found,
      // within half a slot of it.
      const near = before.some(
        (original) =>
          original.kind === track.kind &&
          original.pitch === note.pitchMidi &&
          Math.abs(original.start - note.startTime) <= half + 1e-6,
      );
      assert.ok(
        near,
        `a note at ${note.startTime.toFixed(4)}s has no original within half a slot`,
      );
    }
  }
});

test('the grid does not change the tempo', async () => {
  const snapped = await transcribe(samples, { model, quantise: { grid: 30 } });
  assert.equal(snapped.tempo.bpm, result.tempo.bpm);
});

// --- Reproducibility ---------------------------------------------------

test('produces byte-identical MIDI on a repeat run', async () => {
  const provenance = provenanceFor(model);

  const first = buildMidiFile(result.tracks, result.tempo, result.key, { provenance });
  const second = await transcribe(samples, { model });
  const secondBytes = buildMidiFile(second.tracks, second.tempo, second.key, { provenance });

  assert.deepEqual(
    Buffer.from(first),
    Buffer.from(secondBytes),
    'the same recording produced different MIDI on a second run',
  );
});

test('produces the same notes on a repeat run', async () => {
  const second = await transcribe(samples, { model });

  const flat = (tracks: Track[]) =>
    tracks.flatMap((track) =>
      track.notes.map((note) => ({
        kind: track.kind,
        pitch: note.pitchMidi,
        start: note.startTime,
        duration: note.duration,
        amplitude: note.amplitude,
      })),
    );

  assert.deepEqual(flat(result.tracks), flat(second.tracks));
});

test('stamps the pipeline version and model fingerprint into the MIDI', () => {
  const provenance = provenanceFor(model);
  const bytes = buildMidiFile(result.tracks, result.tempo, result.key, { provenance });
  const text = Buffer.from(bytes).toString('latin1');

  assert.ok(text.includes(PIPELINE_VERSION), 'the file does not name the pipeline version');
  assert.ok(text.includes(model.fingerprint), 'the file does not name the model fingerprint');
});

// --- The model lock ----------------------------------------------------

test('writes a correct key signature', () => {
  // The signed key number of each major key, as a MIDI key signature wants it.
  const expected: Record<string, number> = {
    C: 0, Db: -5, D: 2, Eb: -3, E: 4, F: -1,
    Gb: -6, G: 1, Ab: -4, A: 3, Bb: -2, B: 5,
  };
  const names = Object.keys(expected);

  for (let tonic = 0; tonic < 12; tonic++) {
    for (const mode of ['major', 'minor'] as const) {
      // A minor key is written as its relative major, with the minor flag.
      const relative = mode === 'minor' ? (tonic + 3) % 12 : tonic;
      const name = names[relative];

      const bytes = buildMidiFile(
        result.tracks,
        result.tempo,
        { tonic, mode, confidence: 1 },
        {},
      );

      const read = readKeySignature(bytes);
      assert.equal(read.sf, expected[name], `wrong key number for ${name} ${mode}`);
      assert.equal(read.mi, mode === 'minor' ? 1 : 0, `wrong mode for ${name} ${mode}`);
    }
  }
});

/** Read the key signature out of the raw bytes of a MIDI file. */
function readKeySignature(bytes: Uint8Array): { sf: number; mi: number } {
  const buffer = Buffer.from(bytes);
  for (let i = 0; i < buffer.length - 4; i++) {
    if (buffer[i] === 0xff && buffer[i + 1] === 0x59) {
      return {
        sf: buffer[i + 3] > 127 ? buffer[i + 3] - 256 : buffer[i + 3],
        mi: buffer[i + 4],
      };
    }
  }
  throw new Error('no key signature in the file');
}
test('the weights on disk match the lock file', async () => {
  const bytes = await readFile(MODEL_PATH);
  const digest = await sha256Hex(
    bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer,
  );
  assert.equal(digest, LOCK.files['model.json'].sha256);
  assert.equal(model.fingerprint, LOCK.files['model.json'].sha256);
});

test('refuses a model that does not match the lock file', () => {
  assert.throws(
    () => assertModelMatches('0'.repeat(64), LOCK, 'model.json'),
    /does not match the pinned version/,
  );
});

test('refuses a model that does not fit the pipeline', () => {
  const wrong = {
    ...LOCK,
    contract: { ...LOCK.contract, pitchBins: 128 },
  };
  assert.throws(() => assertContractMatches(wrong), /does not fit this pipeline/);
});

test('the lock file describes the contract the pipeline expects', () => {
  assert.doesNotThrow(() => assertContractMatches(LOCK));
});

// --- Timing ------------------------------------------------------------
//
// A model frame is not the same thing as a moment in the recording. The
// model's windows overlap, so the frames of a window sit closer together
// than the audio they cover. Get this wrong and every note is placed a
// little too late, by a little more on every second of the file, until the
// end of a song is half a second out of step with its beginning.

test('the frame to time mapping never goes backwards', () => {
  let previous = -Infinity;
  for (let frame = 0; frame < 20000; frame += 7) {
    const time = modelFrameToTime(frame);
    assert.ok(time > previous, `frame ${frame} went backwards in time`);
    previous = time;
  }
});

test('a time converts back to the frame it came from', () => {
  for (const frame of [0, 1, 141, 142, 171, 172, 173, 1000, 10319, 13421]) {
    assert.equal(timeToModelFrame(modelFrameToTime(frame)), frame, `frame ${frame} did not survive the round trip`);
  }
});

test('the frame to time mapping covers the whole recording', () => {
  // The recording is 8 seconds long, so the frames that describe it have to
  // reach 8 seconds. If the mapping is off, the tail of the file is lost.
  const frames = 10320;
  assert.ok(
    modelFrameToTime(frames) > 7.9,
    `the last frame only reaches ${modelFrameToTime(frames).toFixed(2)} s`,
  );
});

test('keeps the timing steady over a long recording', async () => {
  // Tone bursts at exactly known times, spread over most of a minute. The
  // point is not that every note is perfect, but that the error does not
  // grow: a note at the end of the file has to be as well placed as one at
  // the start.
  const duration = 48;
  const every = 2;
  const pitch = 69;
  const bursts: number[] = [];

  const signal = new Float32Array(SAMPLE_RATE * duration);
  for (let t = 1; t < duration - 1; t += every) {
    bursts.push(t);
    const start = Math.round(t * SAMPLE_RATE);
    const length = Math.round(0.3 * SAMPLE_RATE);
    for (let i = 0; i < length; i++) {
      const index = start + i;
      if (index >= signal.length) break;
      const attack = Math.min(1, i / 200);
      const decay = Math.exp(-i / (SAMPLE_RATE * 0.25));
      signal[index] = 0.5 * attack * decay * Math.sin((2 * Math.PI * 440 * i) / SAMPLE_RATE);
    }
  }

  const long = await transcribe(signal, { model, detectDrums: false });

  const errors: Array<{ expected: number; error: number }> = [];
  for (const track of long.tracks) {
    for (const note of track.notes) {
      if (note.pitchMidi !== pitch) continue;
      let expected = bursts[0];
      let best = Infinity;
      for (const burst of bursts) {
        const distance = Math.abs(note.startTime - burst);
        if (distance < best) {
          best = distance;
          expected = burst;
        }
      }
      if (best < 0.4) errors.push({ expected, error: (note.startTime - expected) * 1000 });
    }
  }

  assert.ok(
    errors.length >= bursts.length * 0.8,
    `only found ${errors.length} of the ${bursts.length} bursts`,
  );

  errors.sort((a, b) => a.expected - b.expected);
  const first = errors[0].error;
  const last = errors[errors.length - 1].error;

  assert.ok(
    Math.abs(last - first) < 60,
    `the timing drifted by ${(last - first).toFixed(0)} ms across ${duration} seconds`,
  );
  for (const row of errors) {
    assert.ok(
      Math.abs(row.error) < 150,
      `a note at ${row.expected}s was ${row.error.toFixed(0)} ms out of place`,
    );
  }
});
